add_action( 'wp_head', 'perfectpixel_open_graph_tags', 5 );

function perfectpixel_open_graph_tags() {
	// SEO plugins already output Open Graph tags.
	if ( defined( 'WPSEO_VERSION' ) || defined( 'RANK_MATH_VERSION' ) || defined( 'AIOSEO_VERSION' ) || defined( 'SEOPRESS_VERSION' ) ) {
		return;
	}
	$tags = array(
		'og:site_name' => get_bloginfo( 'name' ),
		'og:locale'    => get_locale(),
	);
	if ( is_singular() ) {
		$post                    = get_queried_object();
		$tags['og:type']         = 'article';
		$tags['og:title']        = wp_strip_all_tags( get_the_title( $post ) );
		$tags['og:url']          = get_permalink( $post );
		$excerpt                 = has_excerpt( $post ) ? get_the_excerpt( $post ) : wp_trim_words( strip_shortcodes( $post->post_content ), 30, '…' );
		$tags['og:description']  = wp_strip_all_tags( $excerpt );
		if ( has_post_thumbnail( $post ) ) {
			$tags['og:image'] = get_the_post_thumbnail_url( $post, 'large' );
		}
	} else {
		$tags['og:type']        = 'website';
		$tags['og:title']       = wp_get_document_title();
		$tags['og:url']         = home_url( add_query_arg( array() ) );
		$tags['og:description'] = get_bloginfo( 'description' );
	}
	if ( empty( $tags['og:image'] ) && '' !== trim( '{{og_default_image}}' ) ) {
		$tags['og:image'] = trim( '{{og_default_image}}' );
	}
	foreach ( array_filter( $tags ) as $property => $content ) {
		printf( '<meta property="%s" content="%s">' . "\n", esc_attr( $property ), 'og:url' === $property || 'og:image' === $property ? esc_url( $content ) : esc_attr( $content ) );
	}
}
